sampleCode.java:
import java.util.ArrayList;
import java.util.List;

public class DivisibilityMap {
    public static List<String> divisibilityMap(int n) {
        List<String> result = new ArrayList<>();
        for (int value = 1; value <= n; value++) {
            if (value % 15 == 0) {
                result.add("FizzBuzz");
            } else if (value % 3 == 0) {
                result.add("Fizz");
            } else if (value % 5 == 0) {
                result.add("Buzz");
            } else {
                result.add(String.valueOf(value));
            }
        }
        return result;
    }
}
